"use strict";

exports.exercise = (f) => {
  // Event emitters invoke their listeners through Function.prototype.call.
  const called = f.call(undefined, 2, 3);
  const applied = f.apply(undefined, [4, 5]);
  const bound = f.bind(undefined, 6);
  const boundResult = bound(7);
  const source = Function.prototype.toString.call(f);
  return {
    called,
    applied,
    boundResult,
    isFunction: f instanceof Function,
    kind: typeof f,
    hasFunctionPrototype: Object.getPrototypeOf(f) === Function.prototype,
    boundIsFunction: bound instanceof Function,
    nativeSource: /^function\b[\s\S]*\{\s*\[native code\]\s*\}$/.test(source),
    inheritedSource: f.toString() === source,
  };
};
